<!DOCTYPE html>
<html lang="id"><head><meta charset="UTF-8"><title>{{ $receipt->receipt_number }}</title><style>body{font-family:DejaVu Sans,sans-serif;color:#222;font-size:12px}h1{font-size:22px;margin-bottom:4px}.muted{color:#666}.header{border-bottom:2px solid #333;padding-bottom:12px;margin-bottom:20px}.receipt{float:right;text-align:right}.row{width:100%;margin-bottom:6px}.label{display:inline-block;width:35%;font-weight:bold}.value{display:inline-block;width:63%}.amount{font-size:18px;font-weight:bold;border-top:1px solid #333;border-bottom:1px solid #333;padding:10px 0;margin-top:16px}.footer{margin-top:35px;text-align:center;font-size:11px}</style></head><body><div class="header"><div class="receipt"><strong>E-RECEIPT</strong><br>{{ $receipt->receipt_number }}<br>{{ format_tanggal_id($receipt->issued_at) }}</div><h1>{{ $settings->get('company_name', config('app.name', 'Netivo')) }}</h1><div class="muted">{{ $settings->get('company_address', '-') }}<br>{{ $settings->get('company_phone', '-') }}</div></div><h3>Informasi Customer</h3><div class="row"><span class="label">Nama</span><span class="value">{{ $receipt->payment->bill->customer->user->name }}</span></div><div class="row"><span class="label">Nomor Customer</span><span class="value">{{ $receipt->payment->bill->customer->customer_number }}</span></div><div class="row"><span class="label">Email</span><span class="value">{{ $receipt->payment->bill->customer->user->email }}</span></div><h3>Detail Pembayaran</h3><div class="row"><span class="label">Nomor Tagihan</span><span class="value">{{ $receipt->payment->bill->bill_number }}</span></div><div class="row"><span class="label">Layanan</span><span class="value">{{ $receipt->payment->bill->service->name }}</span></div><div class="row"><span class="label">Periode</span><span class="value">{{ $receipt->payment->bill->period }}</span></div><div class="row"><span class="label">Metode</span><span class="value">{{ $receipt->payment->paymentMethod->name }}</span></div><div class="amount">Total dibayar: {{ format_rupiah($receipt->payment->amount) }}<br><span style="font-size:12px">Status: LUNAS</span></div><div class="footer">Terima kasih atas pembayaran Anda.</div></body></html>
